var productcatalog = flow.get("productCatalog");
var productlist = flow.get("productList");
var totalprice = flow.get("totalPrice");
var messageContent = "🏪 Iacnic Shopping Mall 🏪\nReg No. 483094812093 (52149-K)\n---------------------------------------\n";

if (productlist != null) {
    for (var i = 0; i < productlist.length; i++) {
        var ids = Object.keys(productcatalog);
        for (var j = 0; j < ids.length; j++) {
            if (productcatalog[ids[j]].name == productlist[i].name) {
                messageContent += ids[j] + " " + productlist[i].name + " RM" + productlist[i].price.toFixed(2) + "\n";
            }
        }
    }

    messageContent += "\n                          💳Total Price  RM " + totalprice.toFixed(2) +
        "\n---------------------------------------\n🛒 Thank you for shopping at Iacnic Shopping Mall! 🛒"
} else{
    messageContent += "Shopping Cart Empty."
}

msg.payload = {
    chatId: "974597647",
    messageId: "29",
    sentMessageId: "29",
    type: "message",
    content: messageContent
};
return msg;

