var productlist = flow.get("productList") || [];

var maggie = flow.get("maggieCount") || 0;
var farmfresh = flow.get("farmfreshCount") || 0;
var soya = flow.get("soyaCount") || 0;
var toothpaste = flow.get("toothpasteCount") || 0;
var biscuit = flow.get("biscuitCount") || 0;

var removedproduct = flow.get("removedProduct");

if (flow.get("removeStatus") == "off") {
    if (productlist.length > 0) {
        var lastProduct = productlist[productlist.length - 1];
    }
    if (lastProduct.name == "Maggie") {
        maggie += 1;
    }
    else if (lastProduct.name == "FarmFresh") {
        farmfresh += 1;
    }
    else if (lastProduct.name == "Soya") {
        soya += 1;
    }
    else if (lastProduct.name == "Toothpaste") {
        toothpaste += 1;
    }
    else if (lastProduct.name == "Biscuit") {
        biscuit += 1;
    }
} else if (flow.get("removeStatus") == "on") {
    if (removedproduct == "Maggie") {
        maggie -= 1;
    }
    else if (removedproduct == "FarmFresh") {
        farmfresh -= 1;
    }
    else if (removedproduct == "Soya") {
        soya -= 1;
    }
    else if (removedproduct == "Toothpaste") {
        toothpaste -= 1;
    }
    else if (removedproduct == "Biscuit") {
        biscuit -= 1;
    }
    flow.set("removeStatus", "off");
}

flow.set("maggieCount", maggie);
flow.set("farmfreshCount", farmfresh);
flow.set("soyaCount", soya);
flow.set("toothpasteCount", toothpaste);
flow.set("biscuitCount", biscuit);

return msg;

